from __future__ import annotations

import numpy as np


def energy_kwh(timestamps_s, power_w) -> float:
    """Integrate power over time with the trapezoidal rule and return energy in kWh."""
    t = np.asarray(timestamps_s, dtype=float)
    p = np.asarray(power_w, dtype=float)

    if t.ndim != 1 or p.ndim != 1:
        raise ValueError("timestamps_s and power_w must be 1-D arrays")
    if t.shape[0] != p.shape[0]:
        raise ValueError("timestamps_s and power_w must have the same length")
    if t.size < 2:
        return 0.0

    energy_j = np.trapezoid(p, x=t)
    return float(energy_j / 3.6e6)
